if (msg.topic === "generate-excel") {
    const XLSX = global.get("xlsx"); // 從 global context 取得 xlsx

    if (!msg.payload || !Array.isArray(msg.payload.data)) {
        msg.payload = { error: "缺少數據或格式錯誤" };
        return msg;
    }

    const data = msg.payload.data;
    const selectedDate = msg.payload.date || new Date().toISOString().split("T")[0];
    const projectName = msg.payload.projectName || "未命名專案";
    const filename = `C:/Users/User/.node-red/static/data/詳細資料_${projectName}_${selectedDate}.xlsx`;

    // 建立表格資料：先標題
    const sheetData = [
        ["日期", selectedDate, "", "", "", "", "", ""],
        ["工項", "契約數量", "契約單價", "本日數量", "前日累計數量", "截至今日累計數量", "累計完成金額"]
    ];

    // 加入多筆資料
    data.forEach(item => {
        sheetData.push([
            item.workItem,
            item.contractQuantity,
            item.contractUnitPrice,
            item.todayQuantity,
            item.prevTotalQuantity,
            item.totalQuantity,
            item.totalAmount
        ]);
    });

    // 建立 Excel 工作表與工作簿
    const ws = XLSX.utils.aoa_to_sheet(sheetData);
    ws["!merges"] = [{ s: { r: 0, c: 1 }, e: { r: 0, c: 7 } }]; // 合併「日期」那列

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "詳細資料");

    // 寫入為 Buffer
    const buffer = XLSX.write(wb, { bookType: "xlsx", type: "buffer" });

    // 傳給 write file 節點
    msg.payload = buffer;
    msg.filename = filename;

    return msg;
}

