const PDFDocument = global.get("PDFDocument");
const fs = global.get("fs");

const date = new Date().toISOString().split("T")[0];
const filename = `施工日誌_${date}.pdf`;
const filepath = `C:/Users/user/.node-red/static/data/${filename}`;

const doc = new PDFDocument({ size: "A4", margin: 40 });
doc.registerFont("kai", "C:/Users/User/.node-red/fonts/kaiu.ttf");
doc.font("kai");
doc.lineWidth(0.6);

// 標題與表頭的起始點
const boxX = 482, boxY = 28, boxWidth = 90, boxHeight = 28;

//頁面高度跟底部
const pageHeight = doc.page.height;
const bottomMargin = 60;
const maxY = pageHeight - bottomMargin;

var pageNumber = 1; // 起始頁碼

// 畫標題與表頭
function drawHeader() {
    doc.rect(boxX, boxY, boxWidth, boxHeight).stroke();
    doc.fontSize(18).text("附表四", boxX + 1, boxY + 7, { width: boxWidth, align: "center" });
    [233.7, 233.8, 233.9, 234, 234.1, 234.2, 234.3].forEach(x => doc.fontSize(16).text("公共工程施工日誌", x, 70));
    doc.fontSize(10);
    doc.text("表報編號：", 71, 87.5);
    doc.text("本日天氣：上午：　　  下午：", 71, 101);
    doc.text("填表日期：　　年　　月　　日(星期　)", 336, 101);
}

drawHeader();

// === 通用參數 ===
const startX = 68.5, startY = 111.5, totalWidth = 458, rowHeight = 20, fontSize = 12, lineGap = 2;
const leftColWidth = 222, rightColWidth = 236, leftSubColWidth = 113, rightSubColWidth = 107;
doc.fontSize(fontSize);

// === 共用函式 ===
function drawRow(y, colWidths, labels = [], offsets = []) {
    let x = startX;
    const xList = [x];
    for (let w of colWidths) {
        x += w;
        xList.push(x);
    }
    doc.rect(startX, y, totalWidth, rowHeight).stroke();
    for (let i = 1; i < xList.length; i++) {
        doc.moveTo(xList[i], y).lineTo(xList[i], y + rowHeight).stroke();
    }
    doc.moveTo(startX, y + rowHeight).lineTo(startX + totalWidth, y + rowHeight).stroke();
    for (let i = 0; i < labels.length; i++) {
        const offset = offsets[i] ?? 5;
        doc.text(labels[i], xList[i] + offset, y + 5);
    }
}

//畫格子且讓字置中
function drawRowTextCenter(y, colWidths, labels = [], offsets = []) {
    let x = startX;
    const xList = [x];
    for (let w of colWidths) {
        x += w;
        xList.push(x);
    }

    // 畫外框
    doc.rect(startX, y, totalWidth, rowHeight).stroke();

    // 畫欄位分隔線
    for (let i = 1; i < xList.length; i++) {
        doc.moveTo(xList[i], y).lineTo(xList[i], y + rowHeight).stroke();
    }
    // 畫下邊線
    doc.moveTo(startX, y + rowHeight).lineTo(startX + totalWidth, y + rowHeight).stroke();

    // 寫入文字並置中
    for (let i = 0; i < labels.length; i++) {
        const colX = xList[i];
        const colWidth = colWidths[i];
        const offset = offsets[i] ?? 0;

        doc.text(labels[i], colX + offset, y + 5, {
            width: colWidth,
            align: 'center'
        });
    }
}


function drawRowByPositions(y, xPositions, labels = [], offsets = []) {
    const height = rowHeight;
    doc.rect(xPositions[0], y, xPositions[xPositions.length - 1] - xPositions[0], height).stroke();
    for (let i = 1; i < xPositions.length - 1; i++) {
        doc.moveTo(xPositions[i], y).lineTo(xPositions[i], y + height).stroke();
    }
    doc.moveTo(xPositions[0], y + height).lineTo(xPositions[xPositions.length - 1], y + height).stroke();
    for (let i = 0; i < labels.length; i++) {
        const offset = offsets[i] ?? 5;
        doc.text(labels[i], xPositions[i] + offset, y + 4);
    }
}

function drawAutoHeightRow(y, colWidths, texts, offsets = [], lineGap = 2, fontSize = 12, estimateOnly = false) {
    let x = startX;
    const xList = [x];
    for (let w of colWidths) {
        x += w;
        xList.push(x);
    }

    let maxLineCount = 1;
    for (let i = 0; i < texts.length; i++) {
        const offset = offsets[i] ?? 2;
        const width = colWidths[i] - offset * 2;
        const lineCount = Math.ceil(doc.heightOfString(texts[i], {
            width,
            lineGap
        }) / (fontSize + lineGap));
        if (lineCount > maxLineCount) maxLineCount = lineCount;
    }

    const rowH = (fontSize + lineGap) * maxLineCount + 4;

    if (estimateOnly) return rowH;

    // 畫外框與欄位分隔線
    doc.rect(startX, y, totalWidth, rowH).stroke();
    for (let i = 1; i < xList.length; i++) {
        doc.moveTo(xList[i], y).lineTo(xList[i], y + rowH).stroke();
    }
    doc.moveTo(startX, y + rowH).lineTo(startX + totalWidth, y + rowH).stroke();

    // 寫入文字（置中）
    for (let i = 0; i < texts.length; i++) {
        const offset = offsets[i] ?? 2;
        const colX = xList[i];
        const colWidth = colWidths[i];
        const textWidth = colWidth - offset * 2;

        doc.text(texts[i], colX + offset, y + 2, {
            width: textWidth,
            align: 'center',
            lineGap
        });
    }

    return rowH;
}

function drawFramedTableBlock(dataList, colWidths, colOffsets, sectionTitle, options = {}) {
    const headerFontSize = options.headerFontSize ?? 10;
    const rowFontSize = options.rowFontSize ?? fontSize;
    const rowLineGap = options.rowLineGap ?? lineGap;
    const sectionHeader = [sectionTitle, "", "", "", "", ""];
    const headerHeight = drawAutoHeightRow(currentY, colWidths, sectionHeader, colOffsets, rowLineGap, headerFontSize, true);

    let firstRowHeight = 0;
    if (dataList.length > 0) {
        firstRowHeight = drawAutoHeightRow(currentY + headerHeight, colWidths, Object.values(dataList[0]), colOffsets, rowLineGap, rowFontSize, true);
    }
    if (currentY + headerHeight + firstRowHeight > maxY) {
        drawPageNumber(pageNumber);
        doc.addPage();
        pageNumber++;
        currentY = startY;
    }
    let blockStartY = currentY;
    let blockHeight = headerHeight;

    doc.fontSize(headerFontSize);
    doc.lineWidth(2);
    doc.rect(startX, currentY, totalWidth, headerHeight).stroke();
    doc.lineWidth(0.6);
    let x = startX;
    const xList = [x];
    for (let w of colWidths) {
        x += w;
        xList.push(x);
    }
    for (let i = 1; i < xList.length; i++) {
        doc.moveTo(xList[i], currentY).lineTo(xList[i], currentY + headerHeight).stroke();
    }
    doc.moveTo(startX, currentY + headerHeight).lineTo(startX + totalWidth, currentY + headerHeight).stroke();
    for (let i = 0; i < sectionHeader.length; i++) {
        const offset = colOffsets[i] ?? 5;
        const width = colWidths[i] - 4;
        doc.text(sectionHeader[i], xList[i] + offset, currentY + 2, { width, lineGap });
    }
    currentY += headerHeight;
    doc.fontSize(rowFontSize);

    for (let item of dataList) {
        const values = Object.values(item);
        const estHeight = drawAutoHeightRow(currentY, colWidths, values, colOffsets, rowLineGap, rowFontSize, true);
        if (currentY + estHeight > maxY) {
            doc.lineWidth(2);
            doc.rect(startX, blockStartY, totalWidth, blockHeight).stroke();
            doc.lineWidth(0.6);
            drawPageNumber(pageNumber);
            doc.addPage();
            pageNumber++;
            currentY = startY;
            blockStartY = currentY;
            blockHeight = 0;

            doc.fontSize(headerFontSize);
            doc.lineWidth(2);
            doc.rect(startX, currentY, totalWidth, headerHeight).stroke();
            doc.lineWidth(0.6);
            x = startX;
            const xList = [x];
            for (let w of colWidths) {
                x += w;
                xList.push(x);
            }
            for (let i = 1; i < xList.length; i++) {
                doc.moveTo(xList[i], currentY).lineTo(xList[i], currentY + headerHeight).stroke();
            }
            doc.moveTo(startX, currentY + headerHeight).lineTo(startX + totalWidth, currentY + headerHeight).stroke();
            for (let i = 0; i < sectionHeader.length; i++) {
                const offset = colOffsets[i] ?? 5;
                const width = colWidths[i] - 4;
                doc.text(sectionHeader[i], xList[i] + offset, currentY + 2, { width, lineGap });
            }
            currentY += headerHeight;
            doc.fontSize(rowFontSize);
            blockHeight += headerHeight;
        }
        const usedHeight = drawAutoHeightRow(currentY, colWidths, values, colOffsets, rowLineGap, rowFontSize);
        currentY += usedHeight;
        blockHeight += usedHeight;
    }
    doc.lineWidth(2);
    doc.rect(startX, blockStartY, totalWidth, blockHeight).stroke();
    doc.lineWidth(0.6);
}

function drawTableHeader(y, rowWidths, text, textLeftPadding) {
    drawRowTextCenter(y, rowWidths, text, textLeftPadding);
    return y + rowHeight;
}

//頁碼區塊
function drawPageNumber(pageNumber) {
    doc.fontSize(12).text(`-${pageNumber}-`, 0, doc.page.height - 55, {
        width: doc.page.width,
        align: "center"
    });
}

function breakChineseTextByWidth(text, colWidth, fontSize = 12, padding = 4) {
    if (!doc) throw new Error("PDFKit 'doc' not defined.");

    doc.fontSize(fontSize); // 設定字體大小（如果你有不同欄位大小可以傳進來）

    const availableWidth = colWidth - padding * 2;
    let currentLine = '';
    const lines = [];

    for (let i = 0; i < text.length; i++) {
        const testLine = currentLine + text[i];
        const width = doc.widthOfString(testLine);
        if (width > availableWidth) {
            if (currentLine) lines.push(currentLine); // 避免空行
            currentLine = text[i];
        } else {
            currentLine = testLine;
        }
    }

    if (currentLine) lines.push(currentLine);
    return lines.join('\n');
}



