const xlsx = global.get('xlsx');
const workbook = xlsx.read(msg.payload, { type: 'buffer' });
const sheetName = workbook.SheetNames[1];
const sheet = workbook.Sheets[sheetName];
const rawData = xlsx.utils.sheet_to_json(sheet, { defval: '' });

const result = [];
let currentMain = null;
let currentSection = null;
let currentItem = null;
let currentSubItem = null;

for (let row of rawData) {
    const code = (row["OOOO"] || '').toString().trim();
    const desc = (row["__EMPTY"] || '').toString().trim();

    // 大項（壹、貳…）
    if (code.match(/^[壹貳參肆伍陸柒捌玖拾]+$/)) {
        if (currentSubItem && currentItem) currentItem.children.push(currentSubItem);
        if (currentItem && currentSection) currentSection.children.push(currentItem);
        if (currentSection && currentMain) currentMain.children.push(currentSection);
        if (currentMain) result.push(currentMain);

        currentMain = { type: 'main', item: code, description: desc, children: [] };
        currentSection = null;
        currentItem = null;
        currentSubItem = null;
        continue;
    }

    // 分項（一、二…）
    if (code.match(/^[一二三四五六七八九十]+$/)) {
        if (currentSubItem && currentItem) currentItem.children.push(currentSubItem);
