// === 共用函式 ===
function drawRow(y, options) {
    const {
        colWidths = null,
        xPositions = null,
        labels = [],
        offsets = [],
        height = rowHeight,
        drawBottomLine = true,
        align = 'center',
        fontSize = doc._fontSize ?? 8
    } = options;

    let xList = [];
    if (xPositions) {
        xList = [...xPositions];
    } else if (colWidths) {
        let x = startX;
        xList.push(x);
        for (let w of colWidths) {
            x += w;
            xList.push(x);
        }
    } else {
        throw new Error("drawRow 需要 colWidths 或 xPositions");
    }

    doc.rect(xList[0], y, xList[xList.length - 1] - xList[0], height).stroke();
    for (let i = 1; i < xList.length - 1; i++) {
        doc.moveTo(xList[i], y).lineTo(xList[i], y + height).stroke();
    }
    if (drawBottomLine) {
        doc.moveTo(xList[0], y + height).lineTo(xList[xList.length - 1], y + height).stroke();
    }

    for (let i = 0; i < labels.length; i++) {
        try {
            // 1. 安全轉字串（避免傳入 undefined）
            const labelRaw = labels[i];
            const label = (typeof labelRaw === 'string') ? labelRaw : (labelRaw?.toString?.() ?? '');

            // 2. 安全取得 offset
            const offsetRaw = offsets[i];
            const offset = Number.isFinite(offsetRaw) ? offsetRaw : 0;

            // 3. 安全取得欄位位置
            const xStart = xList[i];
            const xEnd = xList[i + 1];
            if (typeof xStart !== 'number' || typeof xEnd !== 'number') {
                throw new Error(`xStart 或 xEnd 為無效數字：xList[${i}] = ${xStart}, xList[${i + 1}] = ${xEnd}`);
            }
            const colWidth = xEnd - xStart;

            // 4. 計算位置並寫文字
            let textX = xStart;
            const textY = y + (height - fontSize) / 2;
            if (align === 'center') {
                const textWidth = doc.widthOfString(label);
                textX = xStart + (colWidth - textWidth) / 2 + offset;
            } else {
                textX = xStart + offset;
            }

            // 5. 寫入文字
            doc.text(label, textX, textY);
        } catch (err) {
            doc.text(`[ERR]`, startX, y + i * 10); // 簡單標記錯誤
            node.error(`drawRow 第 ${i} 欄錯誤：${err.message}`);
        }
    }

    return xList;
}


//畫格子且讓字置中
function drawRowTextCenter(y, colWidths, labels = [], offsets = []) {
    let x = startX;
    const xList = [x];
    for (let w of colWidths) {
        x += w;
        xList.push(x);
    }

    // 畫外框
    doc.rect(startX, y, totalWidth, rowHeight).stroke();

    // 畫欄位分隔線
    for (let i = 1; i < xList.length; i++) {
        doc.moveTo(xList[i], y).lineTo(xList[i], y + rowHeight).stroke();
    }
    // 畫下邊線
    doc.moveTo(startX, y + rowHeight).lineTo(startX + totalWidth, y + rowHeight).stroke();

    // 寫入文字並置中
    for (let i = 0; i < labels.length; i++) {
        const colX = xList[i];
        const colWidth = colWidths[i];
        const offset = offsets[i] ?? 0;

        doc.text(labels[i], colX + offset, y + 5, {
            width: colWidth,
            align: 'center'
        });
    }
}

function drawAutoHeightRow(y, colWidths, texts, offsets = [], lineGap = 0, fontSize = 8, estimateOnly = false, alignLeftIfMultiline = []) {
    let x = startX;
    const xList = [x];
    for (let w of colWidths) {
        x += w;
        xList.push(x);
    }

    let maxLineCount = 1;
    const lineCounts = [];

    for (let i = 0; i < texts.length; i++) {
        const offset = offsets[i] ?? 2;
        const width = colWidths[i] - offset * 2;

        const text = texts[i] || '';
        const textHeight = doc.heightOfString(text, {
            width,
            lineGap
        });

        // 這裡保留 Math.ceil() 確保高度足夠，但接下來再多加條件避免誤判
        const lineCount = Math.ceil(textHeight / (fontSize + lineGap));

        lineCounts.push(lineCount);
        if (lineCount > maxLineCount) maxLineCount = lineCount;
    }

    const rowH = (fontSize + lineGap) * maxLineCount + 1;
    if (estimateOnly) return rowH;

    // 畫外框與欄位分隔線
    doc.rect(startX, y, totalWidth, rowH).stroke();
    for (let i = 1; i < xList.length; i++) {
        doc.moveTo(xList[i], y).lineTo(xList[i], y + rowH).stroke();
    }
    doc.moveTo(startX, y + rowH).lineTo(startX + totalWidth, y + rowH).stroke();

    // 寫入文字（確保「允許」+「實際超過一行」才置左）
    for (let i = 0; i < texts.length; i++) {
        const offset = offsets[i] ?? 2;
        const colX = xList[i];
        const colWidth = colWidths[i];
        const textWidth = colWidth - offset * 2;

        const text = texts[i] || '';
        let align = 'center';

        // ✅ 必須同時符合「在允許清單內」與「實際行數 > 2」才置左
        if (alignLeftIfMultiline.includes(i) && lineCounts[i] > 2) {
            align = 'left';
        }

        doc.text(text, colX + offset, y + 2, {
            width: textWidth,
            align,
            lineGap
        });
    }

    return rowH;
}

//用於繪製粗框線的特定施工項目的。
function drawFramedTableBlock(dataList, colWidths, colOffsets, sectionTitle, options = {}) {
    const headerFontSize = options.headerFontSize ?? 8;
    const rowFontSize = options.rowFontSize ?? fontSize;
    const rowLineGap = options.rowLineGap ?? lineGap;
    const alignLeftIfMultiline = options.alignLeftIfMultiline ?? [0, 5];

    const sectionHeader = [sectionTitle, "", "", "", "", ""];
    let x = startX;
    const xList = [x];
    for (let w of colWidths) xList.push(x += w);

    function drawHeaderRow(y, forceFixedHeight = null) {
        const headerH = forceFixedHeight ?? drawAutoHeightRow(y, colWidths, sectionHeader, colOffsets, rowLineGap, headerFontSize, true);
        doc.fontSize(headerFontSize).lineWidth(2);
        doc.rect(startX, y, totalWidth, headerH).stroke();
        doc.lineWidth(0.6);
        for (let i = 1; i < xList.length; i++) {
            doc.moveTo(xList[i], y).lineTo(xList[i], y + headerH).stroke();
        }
        doc.moveTo(startX, y + headerH).lineTo(startX + totalWidth, y + headerH).stroke();
        for (let i = 0; i < sectionHeader.length; i++) {
            const offset = colOffsets[i] ?? 5;
            const width = colWidths[i] - 4;
            doc.text(sectionHeader[i], xList[i] + offset, y + 2, { width, lineGap });
        }
        return headerH;
    }


    if (dataList.length === 0) {
        dataList = [{
            item: "",
            unit: "",
            contract_quantity: "",
            todayQuantity: "",
            totalQuantity: "",
            note: ""
        }];
    }

    let blockStartY = currentY;
    let blockHeight = 0;

    let headerH = drawHeaderRow(currentY);
    currentY += headerH;
    blockHeight += headerH;

    doc.fontSize(rowFontSize);

    for (let item of dataList) {
        const values = Object.values(item);
        const estHeight = drawAutoHeightRow(currentY, colWidths, values, colOffsets, rowLineGap, rowFontSize, true, alignLeftIfMultiline);
        if (currentY + estHeight > maxY) {
            doc.lineWidth(2);
            doc.rect(startX, blockStartY, totalWidth, blockHeight).stroke();
            drawPageNumber(pageNumber);
            doc.addPage();
            pageNumber++;
            currentY = startY;
            blockStartY = currentY;
            blockHeight = 0;
            headerH = drawHeaderRow(currentY, headerH);
            currentY += headerH;
            blockHeight += headerH;
            doc.fontSize(rowFontSize);
        }
        const usedHeight = drawAutoHeightRow(currentY, colWidths, values, colOffsets, rowLineGap, rowFontSize, false, alignLeftIfMultiline);
        currentY += usedHeight;
        blockHeight += usedHeight;
    }

    doc.lineWidth(2);
    doc.rect(startX, blockStartY, totalWidth, blockHeight).stroke();
    doc.lineWidth(0.6);
}

//三種資料表的寫法合併
function drawDynamicTableSection(dataList, colWidths, colOffsets, labels, options = {}) {
    const rowFontSize = options.fontSize ?? 8;
    const rowLineGap = options.lineGap ?? 0;
    const alignLeftIfMultiline = options.alignLeftIfMultiline ?? [0, 5];
    //沒數據的時候給一行空白資料列
    const defaultEmptyRow = options.defaultEmptyRow ?? {
        itemName: '',
        unit: '',
        contract_quantity: '',
        todayQuantity: '',
        totalQuantity: '',
        remark: ''
    };

    const rowsToRender = (dataList.length > 0) ? dataList : [defaultEmptyRow];

    for (let row of rowsToRender) {
        const values = [
            row.itemName,
            row.unit,
            row.contract_quantity,
            row.todayQuantity,
            row.totalQuantity,
            row.remark
        ];

        const estimatedHeight = drawAutoHeightRow(currentY, colWidths, values, colOffsets, rowLineGap, rowFontSize, true, alignLeftIfMultiline);

        if (currentY + estimatedHeight > maxY) {
            drawPageNumber(pageNumber);
            doc.addPage();
            pageNumber++;
            currentY = startY;

            // 重畫表頭列
            drawRow(currentY, {
                colWidths,
                labels,
                offsets: colOffsets
            });
            currentY += rowHeight;
        }

        const heightUsed = drawAutoHeightRow(currentY, colWidths, values, colOffsets, rowLineGap, rowFontSize, false, alignLeftIfMultiline);
        currentY += heightUsed;
    }
}

